<?php
require 'header.php';$q=trim($_GET['q']??'');$sql='SELECT c.email,MAX(c.full_name) full_name,MAX(c.phone) phone,COUNT(o.id) order_count,COALESCE(SUM(CASE WHEN o.status NOT IN ("Cancelled","Failed Delivery") THEN o.total ELSE 0 END),0) lifetime_value,MAX(o.created_at) last_order FROM customers c LEFT JOIN orders o ON o.customer_id=c.id';$params=[];if($q!==''){$sql.=' WHERE c.email LIKE ? OR c.full_name LIKE ? OR c.phone LIKE ?';$params=["%$q%","%$q%","%$q%"];}$sql.=' GROUP BY c.email ORDER BY last_order DESC LIMIT 200';$s=db()->prepare($sql);$s->execute($params);$customers=$s->fetchAll();?><div class="admin-title"><p>PEOPLE</p><h2>Manage customers</h2></div><form class="inline-form" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search name, email or phone"><button class="save">Search</button></form><section class="admin-panel"><table><thead><tr><th>Customer</th><th>Phone</th><th>Orders</th><th>Order total</th><th>Last order</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><?=e($c['full_name'])?><br><small><?=e($c['email'])?></small></td><td><?=e($c['phone'])?></td><td><?=$c['order_count']?></td><td><?=money($c['lifetime_value'])?></td><td><?=e($c['last_order']??'—')?></td></tr><?php endforeach?></tbody></table><?php if(!$customers):?><p>No customers found.</p><?php endif?></section><?php require 'footer.php';
